test('model JSON parser handles wrappers and syntax-only normalization without altering exact quotes',()=>{
 const data={story:'흐름',code:'문자열 속 ```json 표시```',quote:'그는 "괜찮아"라고 했다. {기억} <think>인용 속 태그</think>',lines:'첫 줄\n둘째 줄'};
 assert.deepEqual(C.parseModelJSON('설명\n```json\n'+JSON.stringify(data)+'\n```\n끝'),data);
 assert.deepEqual(C.parseModelJSON('<think>분석 {초안}</think>\n'+JSON.stringify(data)),data);
 assert.deepEqual(C.parseModelJSON('{"text":"첫 줄\n둘째 줄", "items":[1,2,],}'),{text:'첫 줄\n둘째 줄',items:[1,2]});
 for(const raw of ['', '{"story":"중간에 끊김', '{"outer":{"inner":1}', '{}\n{}', '[1,2]', '```json\n[{"text":"배열"}]\n```'])assert.throws(()=>C.parseModelJSON(raw),e=>e.code==='MEMORY_FORMAT');
});
test('mismatched quote is quarantined while exact quotes and events continue; acceptance requires current verbatim source',()=>{
 const d=C.empty(),{ms,result}=chapterFixture();result.memories.push({kind:'quote',episodeRef:'current',eventRef:'event1',speaker:'서래',channel:'written',quote:'원문에 없는 약속',text:'원문에 없는 약속',sourceIds:['m1']});result.story+=' 원문에 없는 약속';
 const info=C.applyExtraction(d,result,ms,{quarantineQuotes:true});assert.equal(info.quarantined,1);assert.equal(d.records.filter(r=>r.kind==='event').length,2);assert(d.records.some(r=>r.quote==='기사님 불러'&&r.quoteVerified));assert(!C.injection(d,d.records).text.includes('원문에 없는 약속'));assert.equal(d.quoteReviews.length,1);const review=d.quoteReviews[0];assert.equal(review.eventId,d.records.find(r=>r.text==='기사 호출 요청').id);
 assert.throws(()=>C.acceptQuoteReview(d,review.id,'원문에 없는 약속',ms),/연속된 문자열/);assert.equal(review.status,'pending');assert.throws(()=>C.acceptQuoteReview(d,review.id,'기사님 불러',[{...ms[0],content:'바뀐 원문'},ms[1]]),/변경/);
 const r=C.acceptQuoteReview(d,review.id,'기사님 불러',ms);assert(r.quoteVerified);assert.equal(r.eventId,review.eventId);assert.equal(review.status,'accepted');
});
test('range merge carries quote review sources separately and remaps their chapter/event links',()=>{
 const scratch=C.empty(),{ms,result}=chapterFixture();result.memories.push({kind:'quote',episodeRef:'current',eventRef:'event1',quote:'다르게 적은 발언',text:'후보',sourceIds:['m1']});C.applyExtraction(scratch,result,ms,{quarantineQuotes:true});C.closeEpisode(scratch);const d=C.empty();C.mergeRange(d,scratch,{rangeId:'review_test'});const review=d.quoteReviews[0];assert(review.id.startsWith('range_review_test_'));assert(d.records.some(r=>r.id===review.eventId));assert(d.episodes.some(e=>e.id===review.episodeId));assert(!d.records.some(r=>r.quote==='다르게 적은 발언'));assert(!C.injection(d,d.records).text.includes('다르게 적은 발언'));
});
test('a verified quote with a missing or cross-chapter event link remains a chapter-level quote in tolerant mode',()=>{
 const d=C.empty(),{ms,result}=chapterFixture();result.memories.find(r=>r.kind==='quote').eventRef='missing_event';C.applyExtraction(d,result,ms,{allowUnlinkedQuotes:true,quarantineQuotes:true});let q=d.records.find(r=>r.kind==='quote');assert(q.quoteVerified);assert.equal(q.eventId,undefined);assert(q.eventLinkUnresolved);assert(C.injection(d,d.records).text.includes('기사님 불러'));assert.equal(d.records.filter(r=>r.kind==='event').length,2);
 const d2=C.empty();C.createEpisode(d2,'과거','old');C.saveEvent(d2,{id:'old_event',episodeId:'old',details:{what:'지난 사건'},quotes:[]});C.closeEpisode(d2);C.createEpisode(d2,'현재','new');const x=extraction();x.memories[0].eventRef='old_event';C.applyExtraction(d2,x,messages,{allowUnlinkedQuotes:true});q=d2.records.find(r=>r.kind==='quote');assert.equal(q.episodeId,'new');assert.equal(q.eventId,undefined);assert(q.eventLinkUnresolved);
});

test('body/tracker time precedence, conflicts, missing date and no narrative clock guessing',()=>{
 assert.equal(C.messageClock('시간: 19:30\n저녁 식사', {date:'2027-01-03',time:'19:30'}).label,'2027-01-03 19:30');
 const c=C.messageClock('[2027-01-04 09:15]\n대화',{date:'2027-01-03',time:'20:30'});assert.equal(c.label,'2027-01-04 09:15');assert.equal(c.conflict,true);assert.equal(C.messageClock('2027-01-04',{date:'2027-01-03',time:'20:30'}).label,'2027-01-04');assert.equal(C.messageClock('2027-01-04\n09:15',null).label,'2027-01-04 09:15');
 assert.equal(C.messageClock('시간: 오후 3시 05분',null).label,'15:05');assert.equal(C.messageClock('그가 말했다. 내일 8시 만나자.',null).label,'');
 assert.equal(C.messageClock('시간: 11:20',{worldCustomFields:[{name:'날짜',value:'2027-01-06'}]}).label,'2027-01-06 11:20');
 assert.equal(C.storyClock({time:'2027-02-30 09:00'}),null);
});
