test('compact output fills only duplicate or display fields and does not invent missing memory evidence',()=>{const source={episodes:[{ref:'current',summary:'계속되는 장면',status:'ongoing',sourceIds:['m1']}],currentEpisodeRef:'current',processedIds:['m1'],memories:[{kind:'event',details:{what:'확인된 사건',when:'2027-01-03 19:30'},sourceIds:['m1']},{kind:'quote',quote:'그대로 남긴 말',speaker:'서래',time:'2027-01-03 19:31',sourceIds:['m1']}]};const result=C.completeBatchFields(source,{story:'기존 관계',episode:'이전 장면'});assert.equal(result.story,'기존 관계');assert.equal(result.episode,'계속되는 장면');assert.equal(result.memories[0].text,'확인된 사건');assert.equal(result.memories[1].quote,'그대로 남긴 말');assert.equal(result.memories[1].time,'2027-01-03 19:31');assert.equal(source.story,undefined);assert.equal(C.completeBatchFields({memories:[{kind:'event'}]},{story:'',episode:''}).memories[0].sourceIds,undefined);});

test('only an existing closed chapter can omit an empty source array; evidence is never inferred',()=>{
 const d=C.empty();C.createEpisode(d,'지난 장면','old');d.episodes[0].sourceIds=['m0'];d.processed.m0=C.hash('이전');
 const input={episodes:[{ref:'current',status:'closed'},{ref:'new',status:'ongoing',sourceIds:['m1']}],currentEpisodeRef:'new'};
 const result=C.reconcileChapterSources(d,input,[{id:'m1',content:'다음'}]);assert.deepEqual(result.episodes[0].sourceIds,[]);assert.equal(input.episodes[0].sourceIds,undefined);assert.deepEqual(d.episodes[0].sourceIds,['m0']);
 for(const plan of [{ref:'new',status:'closed'},{ref:'current',status:'ongoing'},{ref:'current',status:'closed',sourceIds:null},{ref:'current',status:'closed',sourceIds:'m1'}])assert.throws(()=>C.reconcileChapterSources(d,{episodes:[plan]},[{id:'m1',content:'다음'}]),e=>e.code==='MEMORY_REFERENCES');
});

test('person names split combined entries, strip OOC suffix and resolve only confirmed aliases without touching quotations',()=>{
 const d=C.empty();d.records=[{id:'a',kind:'event',text:'서재헌이 서래를 만났다.',people:['서재헌, 한서래','서재헌 (사용자 OOC 설정)','서래','간호사','5층 병동 간호사','소속사 고문 변호사']},{id:'q',kind:'quote',text:'인사',speaker:'재헌',recipient:'서래',quote:'서래야.',people:[]}];
 C.setIdentity(d,'한서래',['서래'],true);C.setIdentity(d,'서재헌',['재헌'],true);
 assert.deepEqual(C.personNames(d),['서재헌','한서래']);assert.deepEqual(C.personMemories(d,'한서래').participated.map(r=>r.id),['a','q']);assert.equal(d.records[1].speaker,'재헌');assert.equal(d.records[1].quote,'서래야.');
 C.setIdentity(d,'한서래',[],true);assert.equal(C.canonicalName(d,'서래'),'서래');assert.throws(()=>C.setIdentity(d,'다른 사람',['재헌'],true),/이미 연결/);
 d.hiddenPeople=['서재헌'];assert(!C.personNames(d).includes('서재헌'));assert.equal(d.records.length,2);
});
