test('quote source completion rejects absent, repeated, paraphrased and supplied invalid evidence instead of guessing',()=>{
 const d=C.empty(),quote={kind:'quote',text:'이미 있는 설명',quote:'약속할게.'},make=sourceIds=>({memories:[{...quote,...sourceIds}]});
 assert.equal(C.completeBatchFields(make({}),d,[{id:'m',content:'약속할게.'}]).memories[0].sourceIds[0],'m');
 for(const ms of [[],[{id:'m',content:'약속한다.'}],[{id:'m',content:'약속할게.'},{id:'n',content:'약속할게.'}]])assert.equal(C.completeBatchFields(make({}),d,ms).memories[0].sourceIds,undefined);
 for(const sourceIds of [null,'m',['invented']])assert.deepEqual(C.completeBatchFields(make({sourceIds}),d,[{id:'m',content:'약속할게.'}]).memories[0].sourceIds,sourceIds);
 assert.deepEqual(C.completeBatchFields(make({sourceIds:[]}),d,[{id:'m',content:'약속할게.'}]).memories[0].sourceIds,['m']);
});
test('validation diagnostics distinguish missing text from missing source lists and invalid source IDs and remain atomic',()=>{
 for(const patch of [{text:''},{sourceIds:undefined},{sourceIds:[]},{sourceIds:['unknown']}]){const d=C.empty(),{ms,result}=chapterFixture();Object.assign(result.memories[0],patch);const before=JSON.stringify(d);assert.throws(()=>C.applyExtraction(d,result,ms),e=>e.code==='MEMORY_REFERENCES'&&e.message.includes('기억 #1')&&e.message.includes(patch.text===''?'text':'sourceIds'));assert.equal(JSON.stringify(d),before);}
});

