 const chapters=C.acceptChapterWindow({chapters:[{startUnitId:units[1].id,endUnitId:units.at(-1).id,title:'새로운 장면',summary:'새로운 장면에서 취향을 밝혔다.'}]},units.slice(1),first);const ids=d.records.map(r=>r.id);C.assignChapters(d,chapters,ms);assert.deepEqual(d.records.map(r=>r.id),ids);assert.equal(d.records[0].episodeId,d.records[1].episodeId);assert.notEqual(d.records[0].episodeId,d.records[2].episodeId);assert.equal(d.episodes.length,2);assert.equal(d.episodes[1].status,'ongoing');
