test('gap repair appends evidence-backed memories without altering prior memories or fabricating source IDs',()=>{
 const ms=[{id:'a',content:'조건은 오늘 하루뿐이야.'},{id:'b',content:'새로운 장면.'}],base=C.alignReviewCoverage({processedIds:['a','b'],memories:[{ref:'e',kind:'event',text:'보존할 기존 상세 내용',sourceIds:['b']}],coverage:[{sourceId:'a',outcome:'captured',reason:'조건을 보존했다는 주장'},{sourceId:'b',outcome:'captured',reason:'새 장면'}]});
 const repair={additions:[{ref:'new_condition',kind:'event',text:'오늘 하루로 범위를 한정했다.',sourceIds:['a'],sourceEvidence:[{sourceId:'a',excerpt:'오늘 하루뿐이야.'}]}],coverageUpdates:[{sourceId:'a',outcome:'captured',reason:'조건을 추가로 보존했다.',evidence:'조건은 오늘 하루뿐이야.'}]};const fixed=C.mergeReviewRepair(base,repair,ms);assert.equal(fixed.memories[0].text,base.memories[0].text);assert.deepEqual(fixed.memories[0].sourceIds,['b']);assert.equal(fixed.memories.length,2);assert.deepEqual(fixed.coverage[0].memoryRefs,['new_condition']);assert.equal(base.memories.length,1);
 for(const mutate of [r=>r.additions[0].sourceEvidence[0].excerpt='없는 문장',r=>r.additions[0].sourceIds=['invented'],r=>r.additions[0].ref='e',r=>r.coverageUpdates[0].sourceId='b',r=>r.additions=[]]){const bad=C.clone(repair);mutate(bad);assert.throws(()=>C.mergeReviewRepair(base,bad,ms),e=>e.code==='MEMORY_REFERENCES');}
});

