 const once=C.mergeReviewRepair(base,repair('a'),ms,{allowPartial:true});assert.equal(once.memories.length,1);assert.deepEqual(C.reviewGaps(once).map(c=>c.sourceId),['b']);assert.throws(()=>C.validateDetailReview(once,ms));const final=C.mergeReviewRepair(once,repair('b'),ms,{allowPartial:true});C.validateDetailReview(final,ms);assert.equal(final.memories.length,2);assert.equal(base.memories.length,0);
