test('supporting evidence restores a unique whole-sentence omission using only the original paragraph',()=>{
 const left='The first verified sentence has enough detail. ',missing='A middle sentence was omitted. ',right='The last verified sentence also has enough detail.';
 const full='"'+left+missing+right+'"',short='"'+left+right+'"',option={restoreOmissions:true};
 assert.equal(C.matchEvidence(full,short),null);assert.equal(C.matchEvidence(full,short,option),full);
 assert.equal(C.matchEvidence(full,short.replace('last','other'),option),null);
 assert.equal(C.matchEvidence('"'+left+'10 more words '+right+'"',short,option),null);
 assert.equal(C.matchEvidence('"'+left+'A'.repeat(201)+'. '+right+'"',short,option),null);
 assert.equal(C.matchEvidence('"'+left+'A different speaker said "no". '+right+'"',short,option),null);
 assert.equal(C.matchEvidence('"'+left+missing+'\n\n'+right+'"',short,option),null);
 assert.equal(C.matchEvidence(full+'\n\n'+full,short,option),null);
 const ms=[{id:'a',content:full}],base=C.alignReviewCoverage({processedIds:['a'],memories:[],coverage:[{sourceId:'a',outcome:'captured',reason:'누락'}]});
 const repair={additions:[{ref:'r',kind:'event',text:'보완 사건',sourceIds:['a'],sourceEvidence:[{sourceId:'a',excerpt:short}]}],coverageUpdates:[{sourceId:'a',outcome:'captured',reason:'사건 보완'}]};
 const result=C.mergeReviewRepair(base,repair,ms);assert.equal(result.memories[0].sourceEvidence[0].excerpt,full);assert.equal(result.memories[0].sourceEvidence[0].reportedExcerpt,short);assert.equal(repair.additions[0].sourceEvidence[0].excerpt,short);
 assert.throws(()=>C.mergeReviewRepair(base,{additions:[],coverageUpdates:[{sourceId:'a',outcome:'context_only',reason:'반복',evidence:short}]},ms),/원문 근거/);
 assert.throws(()=>C.applyExtraction(C.empty(),{story:'',episode:'',processedIds:['a'],memories:[{kind:'quote',text:'발언',quote:short,speaker:'인물',sourceIds:['a']}]},ms),/다른 인용/);
});

