 for(const change of [r=>r.additions[0].sourceEvidence[0].segmentId='invented',r=>r.additions[0].sourceEvidence[0].segmentId=index[1].segments[0].segmentId,r=>r.additions[0].sourceEvidence[0].excerpt='원문에 없는 외형 칭찬',r=>r.additions[0].sourceEvidence[0].sourceId='b']){const bad=C.clone(repair);change(bad);assert.throws(()=>C.mergeReviewRepair(base,bad,ms),e=>e.code==='MEMORY_REFERENCES');}
 const context={additions:[],coverageUpdates:[{sourceId:'a',outcome:'context_only',reason:'반복 질문임을 확인했다.',evidenceSegmentId:index[0].segments[0].segmentId}]};assert.equal(C.mergeReviewRepair(base,context,ms).coverage[0].repairEvidence,'첫 질문.');context.coverageUpdates[0].evidenceSegmentId=index[1].segments[0].segmentId;assert.throws(()=>C.mergeReviewRepair(base,context,ms),/문단 번호/);
