 assert.throws(()=>C.applyExtraction(C.empty(),result,ms),/없는 ID/);const d=C.empty();C.applyExtraction(d,result,ms,{supportingMessages:before});assert.deepEqual(Object.keys(d.processed),['n']);assert.deepEqual(d.records[0].sourceIds,['p','n']);assert.equal(d.records[0].sourceHashes.p,C.hash(before[0].content));assert.equal(d.records[0].sourcePositions.p,130);assert.equal(d.records[1].quoteVerified,true);assert.deepEqual(d.episodes[0].sourceIds,['n']);
 for(const change of [r=>r.memories[0].sourceIds=['invented','n'],r=>r.memories[0].sourceIds=['p'],r=>r.processedIds=['p','n']]){const bad=C.clone(result);change(bad);assert.throws(()=>C.applyExtraction(C.empty(),bad,ms,{supportingMessages:before}));}
 const bad=C.clone(result);bad.memories[1].quote='담요를 주지 않을게.';const quarantined=C.empty();C.applyExtraction(quarantined,bad,ms,{supportingMessages:before,quarantineQuotes:true});assert.equal(quarantined.quoteReviews.length,1);assert.equal(quarantined.quoteReviews[0].sources[0].hash,C.hash(before[0].content));assert.equal(quarantined.records.filter(r=>r.kind==='quote').length,0);
