test('gap repair validates prior-context paragraph evidence while coverage remains limited to current messages',()=>{
 const before=[{id:'p',content:'원문 제안.'}],ms=[{id:'n',content:'제안 수락.'}],base=C.alignReviewCoverage({processedIds:['n'],memories:[],coverage:[{sourceId:'n',outcome:'captured',reason:'누락'}]}),repair={additions:[{ref:'e',kind:'event',text:'제안 수락',sourceIds:['p','n'],sourceEvidence:[{sourceId:'p',segmentId:'p:p1'},{sourceId:'n',segmentId:'n:p1'}]}],coverageUpdates:[{sourceId:'n',outcome:'captured',reason:'제안과 수락 연결'}]};
 assert.throws(()=>C.mergeReviewRepairProgress(base,repair,ms));const result=C.mergeReviewRepairProgress(base,repair,ms,{supportingMessages:before});C.validateDetailReview(result,ms);assert.deepEqual(result.memories[0].sourceIds,['p','n']);assert.equal(result.coverage.length,1);assert.equal(result.memories[0].sourceEvidence[0].excerpt,'원문 제안.');
 const units=C.chapterUnits({records:result.memories},[...before,...ms]);assert.equal(units.length,1);assert.deepEqual(units[0].sourceIds,['p','n']);
});

test('draft audit reports bad source IDs and event links without rewriting or discarding the candidate',()=>{
 const ms=[{id:'source_exact',content:'확인된 원문.'}],raw={processedIds:['source_exact'],memories:[{ref:'event_1',kind:'event',text:'제안',sourceIds:['source_exacT'],eventRef:'quote_1'},{ref:'quote_1',kind:'quote',text:'발언',sourceIds:['source_exact'],quote:'없는 발언',eventRef:'event_1'}]},before=JSON.stringify(raw),issues=C.auditDetailDraft(raw,ms);
 assert(issues.some(e=>e.code==='unknown_source_ids'&&e.invalidIds.includes('source_exacT')));assert(issues.some(e=>e.code==='invalid_event_ref'&&e.eventRef==='quote_1'));assert(issues.some(e=>e.code==='non_quote_event_ref'));assert(issues.some(e=>e.code==='quote_mismatch'));assert.equal(JSON.stringify(raw),before);assert.throws(()=>C.auditDetailDraft({processedIds:[],memories:null},ms));
 const fixed=C.detailedResult({...raw,memories:[{ref:'event_1',kind:'event',text:'확인된 원문.',sourceIds:['source_exact']}]},C.empty(),ms,{});assert.deepEqual(C.auditDetailDraft(fixed,ms),[]);const d=C.empty();C.applyExtraction(d,fixed,ms);assert.equal(d.records.length,1);
});

test('chapter JSON repair fixes only a missing quote on the structural boolean key',()=>{
 const expected={chapters:[{startUnitId:'unit_a',endUnitId:'unit_b',continuesPrevious:true,title:'기존 장면의 계속',summary:'대사 "원문 그대로"와 줄바꿈\n보존'},{startUnitId:'unit_c',endUnitId:'unit_d',continuesPrevious:false,title:'새 장면',summary:'내용을 바꾸지 않는다.'}]},good=JSON.stringify(expected),bad=good.replace(/"continuesPrevious":(true|false)/g,'"continuesPrevious:$1');
 assert.throws(()=>C.parseModelJSON(bad));const fixed=C.repairChapterJSON(bad);assert.equal(fixed.repairedKeys,2);assert.equal(fixed.text,good);assert.deepEqual(C.parseModelJSON(fixed.text),expected);
 const validText=JSON.stringify({summary:'기호 {"continuesPrevious:true,"title": 를 그대로 보존',list:['continuesPrevious:true,','"continuesPrevious:false}'],nested:{'continuesPrevious:true,':'문자열 키'}});assert.deepEqual(C.repairChapterJSON(validText),{text:validText,repairedKeys:0});
 const truncated=bad.slice(0,-5),restored=C.repairChapterJSON(truncated);assert.throws(()=>C.parseModelJSON(restored.text));const other='{"chapters":[{"unknown:true,"title":"다른 문법 오류"}]}';assert.equal(C.repairChapterJSON(other).text,other);assert.throws(()=>C.parseModelJSON(other));
});

test('syntax repair never supplies chapter boundaries or bypasses contiguous-coverage validation',()=>{
 const raw='{"chapters":[{"startUnitId":"invented","endUnitId":"u1","continuesPrevious:false,"title":"제목","summary":"설명"}]}',parsed=C.parseModelJSON(C.repairChapterJSON(raw).text);assert.equal(parsed.chapters[0].startUnitId,'invented');assert.throws(()=>C.acceptChapterWindow(parsed,[{id:'u1',sourceIds:['m1']}],[]),/범위/);
});

test('numbered chapter ends resolve to real atomic units without copying opaque IDs or losing source coverage',()=>{
 const units=[{id:'opaque_a',sourceIds:['m1','m2']},{id:'opaque_b',sourceIds:['m3']},{id:'opaque_c',sourceIds:['m4','m5']}],prior=[{id:'old_chapter',title:'이전 장면',summary:'기존 내용',sourceIds:['p1']}],raw={chapters:[{endUnitNumber:1,continuesPrevious:true,title:'계속',summary:'기존과 새 내용'},{endUnitNumber:3,continuesPrevious:false,title:'다음 장면',summary:'후속 장면'}]},before=JSON.stringify({units,prior,raw});
 const result=C.acceptNumberedChapterWindow(raw,units,prior);assert.deepEqual(result[0].sourceIds,['p1','m1','m2']);assert.deepEqual(result[1].sourceIds,['m3','m4','m5']);assert.equal(result[0].id,'old_chapter');assert.equal(result[0].summary,'기존과 새 내용');assert.equal(JSON.stringify({units,prior,raw}),before);
 for(const ends of [[0,3],[1,4],[1,1,3],[2,1,3],[1.5,3],['1',3],[1]])assert.throws(()=>C.acceptNumberedChapterWindow({chapters:ends.map(endUnitNumber=>({endUnitNumber,continuesPrevious:false,title:'제목',summary:'내용'}))},units));
 assert.throws(()=>C.acceptNumberedChapterWindow({chapters:[{startUnitId:'invented',endUnitNumber:3,continuesPrevious:false,title:'제목',summary:'내용'}]},units),/범위/);
 assert.throws(()=>C.acceptNumberedChapterWindow({chapters:[{endUnitNumber:3,continuesPrevious:'false',title:'제목',summary:'내용'}]},units),/boolean/);
 assert.throws(()=>C.acceptNumberedChapterWindow({chapters:[{startUnitId:'opaque_a',endUnitId:'invented',continuesPrevious:false,title:'제목',summary:'내용'}]},units),/endUnitNumber/);
});

test('slash-combined people split across views while original dialogue and metadata stay intact',()=>{
 const d=C.empty();d.records=[{id:'e',kind:'event',text:'약속했다',people:['서재헌/한서래'],sourceIds:['m']},{id:'q',kind:'quote',text:'발언',speaker:'재헌',recipient:'서래',quote:'서재헌/한서래',sourceIds:['n']}];const before=JSON.stringify(d.records);
 assert.deepEqual(C.personNames(d),['서재헌','한서래']);
 assert.deepEqual(C.personMemories(d,'서래').participated.map(r=>r.id),['e','q']);
 assert.deepEqual(C.cleanNames('서재헌／한서래 · 전명후 & 한기현'),['서재헌','한서래','전명후','한기현']);
 assert.equal(JSON.stringify(d.records),before);
});
test('unique Korean short names resolve for profile lookup, recall aliases and injection',()=>{
 const d=C.empty();d.records=[{id:'e',kind:'event',people:['서재헌','서래'],text:'조건을 정했다',sourceIds:['a']},{id:'f',kind:'fact',subject:'한서래',section:'role',text:'한서래는 배우다',sourceIds:['b']}];
 assert.equal(C.canonicalName(d,'서래'),'한서래');assert.deepEqual(C.personIdentity(d,'한서래').aliases,['서래']);
 assert.deepEqual(C.personProfile(d,'서래').map(r=>r.id),['f']);
 assert(C.injection(d,[d.records[0]]).text.includes('"aliases":["서래"]'));
 assert(C.injection(d,[d.records[0]]).ids.includes('f'));
});
test('ambiguous given names and manual choices do not auto-merge or lose hidden people state',()=>{
 const d=C.empty();d.records=[{id:'a',kind:'event',people:['한서래','견서래','서래'],text:'동명이인',sourceIds:['a']}];
 assert.equal(C.canonicalName(d,'서래'),'서래');assert.equal(C.personNames(d).length,3);
 C.setIdentity(d,'한서래',['서래'],true);assert.equal(C.canonicalName(d,'서래'),'한서래');
 C.setIdentity(d,'한서래',[],true);assert.equal(C.canonicalName(d,'서래'),'서래');
 d.records[0].people=['한서래','서래'];assert.equal(C.canonicalName(d,'서래'),'서래');
 const x=C.empty();x.records=[{id:'a',kind:'event',people:['한서래','서래'],text:'대화'}];x.hiddenPeople=['서래'];assert(!C.personNames(x).includes('한서래'));
});
test('recurring unnamed roles are listed using distinct evidence rather than duplicated memory count',()=>{
 const d=C.empty();d.records=[{id:'a',kind:'event',people:['서재헌의 매니저','한서래의 매니저','간호사','환자'],text:'일정 전달',sourceIds:['a']},{id:'b',kind:'quote',speaker:'서재헌의 매니저',recipient:'서재헌',text:'답변',sourceIds:['a']}];
 assert(!C.personNames(d).includes('서재헌의 매니저'));
 d.records.push({id:'c',kind:'event',people:['서재헌의 매니저','환자'],text:'다음 일정 변경',sourceIds:['b']});
 assert(C.personNames(d).includes('서재헌의 매니저'));assert(!C.personNames(d).includes('한서래의 매니저'));assert(!C.personNames(d).includes('간호사'));assert(!C.personNames(d).includes('환자'));
 assert.equal(C.canonicalName(d,'서재헌의 매니저'),'서재헌의 매니저');
 d.records.push({id:'d',kind:'event',people:['한서래의 매니저'],text:'다른 일정',sourceIds:['c']});
 assert(C.personNames(d).includes('한서래의 매니저'));
 assert(!C.personMemories(d,'한서래의 매니저').participated.some(r=>r.id==='c'));
 d.records[2].deleted=true;assert(!C.personNames(d).includes('서재헌의 매니저'));
});

test('different verbatim lines with the same source and description remain separate, repeat idempotently and keep event links',()=>{
 const d=C.empty(),source={id:'one',role:'assistant',content:'매니저 | "삼십 분 잡아야 돼요."\n서재헌 | "그럼 바로 가자."\n서재헌 | "커피 하나 사줘."'};
 const result={story:'',episode:'이동',processedIds:['one'],memories:[{ref:'e',kind:'event',text:'이동과 커피 요청',sourceIds:['one']},...['삼십 분 잡아야 돼요.','그럼 바로 가자.','커피 하나 사줘.'].map((quote,i)=>({ref:'q'+i,kind:'quote',text:'관련 발언',speaker:i?'서재헌':'매니저',channel:'spoken',quote,eventRef:'e',sourceIds:['one']}))]};
 C.applyExtraction(d,result,[source]);assert.equal(d.records.filter(r=>r.kind==='quote').length,3);assert.equal(new Set(d.records.filter(r=>r.kind==='quote').map(r=>r.id)).size,3);assert(d.records.filter(r=>r.kind==='quote').every(r=>r.eventId===d.records.find(e=>e.kind==='event').id&&r.quoteVerified));
 const ids=d.records.map(r=>r.id);C.applyExtraction(d,result,[source]);assert.deepEqual(d.records.map(r=>r.id),ids);
 const legacy=C.empty(),row=d.records.find(r=>r.quote==='그럼 바로 가자.'),oldId='mem_'+C.hash('one|quote|관련 발언');legacy.records=[{...row,id:oldId,manualEdited:true}];C.applyExtraction(legacy,result,[source]);assert.equal(legacy.records.filter(r=>r.kind==='quote').length,3);assert(legacy.records.find(r=>r.quote==='그럼 바로 가자.').id===oldId);assert(legacy.records.find(r=>r.id===oldId).manualEdited);
});
test('missing descriptions may fall back to the same speaker label without collapsing exact quotes',()=>{
 const d=C.empty(),ms=[{id:'m',content:'가자. 커피 사줘.'}];const input=C.completeBatchFields({story:'',episode:'',processedIds:['m'],memories:[{ref:'a',kind:'quote',quote:'가자.',speaker:'서재헌',sourceIds:['m']},{ref:'b',kind:'quote',quote:'커피 사줘.',speaker:'서재헌',sourceIds:['m']}]},d,ms);C.applyExtraction(d,input,ms);assert.equal(d.records.length,2);assert.equal(d.records[0].text,d.records[1].text);assert.notEqual(d.records[0].id,d.records[1].id);
});
test('dialogue inventory preserves all six labelled original lines and excludes inline remembered words and system labels',()=>{
 const lines=[['매니저','형님, 새해 복 많이 받으세요. 얼굴이 좀 부으셨는데 어제 잠을 못 주무셨어요?'],['서재헌','새해라 그냥 산책했어. 리딩 장소까지 이십 분이면 되지?'],['매니저','지금 출발하면 삼십 분 잡아야 돼요. 새해라 첫 신호가 다 길어서.'],['서재헌','그럼 바로 가자. 그리고 이따 커피 하나 사줘. 진한 걸로.'],['매니저','형님, 커피 드릴까요. 아까 사달라 하셔서.'],['서재헌','어, 고맙다. 여기 두고.']];
 const source={id:'Lz7pGEZ3a3tuQmUidpQ8z',content:"이전에 '하루만으로 만족할 수 있을지 어디 한번 보자'라고 썼다.\n"+lines.map(([speaker,line])=>speaker+' | "'+line+'"').join('\n\n')+'\n시스템 | "전송 실패"'};
 const before=JSON.stringify(source),inventory=C.dialogueCandidates([source]);assert.equal(inventory.length,6);assert.deepEqual(inventory.map(c=>[c.speaker,c.quote]),lines);assert(inventory.every(c=>source.content.includes(c.quote)&&c.sourceId===source.id));assert.equal(new Set(inventory.map(c=>c.candidateId)).size,6);assert.equal(JSON.stringify(source),before);
});

test('quote enrichment preserves story and events while adding exact quotes and connecting existing unlinked lines',()=>{
 const d=C.empty();d.story='줄거리';d.episode='현재 장면';d.episodes=[{id:'ep',title:'협의',sourceIds:['a','b']}];d.records=[{id:'e1',kind:'event',episodeId:'ep',text:'학비 상환 조건 제안',sourceIds:['a']},{id:'e2',kind:'event',episodeId:'ep',text:'제안 거절',sourceIds:['b']},{id:'old',kind:'quote',quote:'이자도 갚아.',speaker:'서재헌',channel:'spoken',sourceIds:['a'],quoteVerified:true},{id:'empty',kind:'quote',text:'인용 없는 기록',sourceIds:['b']}];
 const ms=[{id:'a',rowid:1,content:'서재헌 | "이자도 갚아."'},{id:'b',rowid:2,content:'한서래 | "공부 하나는 할 수 있어."'}],result={reviewedSourceIds:['a','b'],quotes:[{quote:'이자도 갚아.',speaker:'서재헌',channel:'spoken',sourceIds:['a'],eventId:'e1',linkReason:'상환 조건'},{quote:'공부 하나는 할 수 있어.',speaker:'한서래',channel:'spoken',sourceIds:['b'],eventId:'e2',linkReason:'거절 응답'}]};
 const events=JSON.stringify(d.records.filter(r=>r.kind==='event'));assert.deepEqual(C.mergeQuoteEnrichment(d,result,ms),{added:1,linked:1});assert.equal(d.records.find(r=>r.id==='old').eventId,'e1');assert.equal(d.records.filter(C.hasQuote).length,2);assert.equal(d.records.find(r=>r.speaker==='한서래').eventId,'e2');assert.equal(JSON.stringify(d.records.filter(r=>r.kind==='event')),events);assert.equal(d.story,'줄거리');assert.equal(d.episode,'현재 장면');assert(d.records.some(r=>r.id==='empty'));assert(!C.injection(d,d.records).text.includes('인용 없는 기록'));assert.deepEqual(C.mergeQuoteEnrichment(d,result,ms),{added:0,linked:0});
});
test('quote enrichment rejects invented or unrelated evidence atomically, including cross-chapter links',()=>{
 const d=C.empty();d.episodes=[{id:'a',sourceIds:['a']},{id:'b',sourceIds:['b']}];d.records=[{id:'ea',kind:'event',text:'A',episodeId:'a',sourceIds:['a']},{id:'eb',kind:'event',text:'B',episodeId:'b',sourceIds:['b']}];const ms=[{id:'a',content:'약속한다.'},{id:'b',content:'거절한다.'}],base={reviewedSourceIds:['a','b'],quotes:[{quote:'약속한다.',speaker:'서재헌',channel:'spoken',sourceIds:['a'],eventId:'ea'}]},before=JSON.stringify(d);
 for(const patch of [{quote:'없는 발언'},{eventId:'invented'},{eventId:'eb'},{sourceIds:['invented']},{quote:''}]){const bad=C.clone(base);Object.assign(bad.quotes[0],patch);assert.throws(()=>C.mergeQuoteEnrichment(d,bad,ms));assert.equal(JSON.stringify(d),before);}
 const mixed=C.clone(base);mixed.quotes.push({...base.quotes[0],sourceIds:['a','b']});assert.throws(()=>C.mergeQuoteEnrichment(d,mixed,ms),/근거|챕터/);assert.equal(JSON.stringify(d),before);
});
