 for(const change of [q=>q.sourceIds=['unknown'],q=>q.quote='만든 대사',q=>q.eventRef='missing']){const bad=C.clone(raw),target=C.empty();change(bad.memories[1]);assert.throws(()=>C.applyExtraction(target,bad,[now],{supportingMessages:[old]}));assert.equal(target.records.length,0);}
