 const result={story:'',episode:'약속 이행 요청',processedIds:['now'],memories:[{ref:'request',kind:'event',text:now.content,sourceIds:['now'],memoryLinks:[{recordId:past.id,reason:'복귀하면 피어싱을 끼워주겠다는 약속의 이행을 요구함'}]}]};C.applyExtraction(d,result,[now],{supportingMessages:[old]});const next=d.records.find(r=>r.sourceIds.includes('now'));assert.equal(next.memoryLinks[0].recordId,past.id);assert.deepEqual(next.sourceIds,['now']);assert.notEqual(next.episodeId,past.episodeId);assert.equal(C.chapterUnits(d,[old,now]).length,2);
 const merged=C.empty();C.mergeRange(merged,d,{rangeId:'full_history',mode:'full',sourceIds:['old','now'],from:1,to:20,count:2});assert(merged.records.find(r=>r.id==='range_full_history_'+next.id).memoryLinks.some(l=>l.recordId==='range_full_history_'+past.id));
 const invalid=C.clone(result);invalid.memories[0].memoryLinks[0].recordId='invented';assert.throws(()=>C.applyExtraction(C.empty(),invalid,[now],{supportingMessages:[old]}),/근거 기억 링크/);
 C.deleteMemories(d,[past.id]);assert(!next.deleted);assert.equal(next.memoryLinks.length,0);
