 const clock=C.storyClock({time:'27-01-01 23:47경'});assert.equal(clock.date,Date.UTC(2027,0,1));assert.equal(clock.minute,1427);assert.equal(C.storyClock({time:'127-01-01'}),null);assert.equal(C.storyClock({time:'27-02-30'}),null);
