function continuityFixture(){
 const old={id:'morning',rowid:1,content:'아침 회복실에서 울며 손바닥에 볼을 부볐다.'},now={id:'night',rowid:12,content:'아침에 울었던 일을 묻고 성적표를 찾지 않은 이유를 물었다.'};const d=C.empty();d.records=[{id:'old',kind:'event',episodeId:'morning-ep',text:'회복실에서 울었다.',time:'27-01-04 08:20',sourceIds:[old.id],sourceHashes:{morning:C.hash(old.content)}},{id:'now',kind:'event',episodeId:'night-ep',text:'성적표 질문.',time:'27-01-05 00:37',sourceIds:[now.id],sourceHashes:{night:C.hash(now.content)}}];
 const result={reviewedSourceIds:['night'],updates:[{eventId:'now',text:'서재헌은 아침 회복실에서 한서래가 울었던 일을 짚은 뒤, 낮에 찾던 성적표를 포기한 이유를 물었다.',sourceEvidence:[{sourceId:'night',segmentId:'night:p1'}],memoryLinks:[{recordId:'old',reason:'현재 대화가 회상한 아침 회복실의 울음',relation:'cause',targetEvidence:[{sourceId:'morning',segmentId:'morning:p1'}]}]}]};return {d,old,now,result};
}
test('continuity enrichment preserves IDs, original chronology, existing prose and creates evidence-backed bidirectional recall',()=>{
 const {d,old,now,result}=continuityFixture();const n=C.mergeContinuity(d,result,[now],[old]);assert.equal(n.updated,1);assert.equal(n.linked,1);assert.equal(d.records.length,2);const r=d.records[1];assert(r.text.startsWith('성적표 질문.'));assert.deepEqual(r.sourceIds,['night']);assert.equal(r.time,'27-01-05 00:37');assert.equal(r.memoryLinks[0].recordId,'old');assert.equal(r.continuitySupplements[0].sourceHashes.morning,C.hash(old.content));assert.deepEqual(C.linkedMemoryContext(d,[d.records[0]]).map(r=>r.id),['now']);
 assert.deepEqual(C.mergeContinuity(d,result,[now],[old]),{updated:0,linked:0});
});
for(const bad of ['invented-target','missing-past','changed-past','wrong-paragraph','manual','future','same-event-cross-date'])test('continuity enrichment atomically rejects '+bad,()=>{
 const {d,old,now,result}=continuityFixture();let past=[old];if(bad==='invented-target')result.updates[0].memoryLinks[0].recordId='invented';if(bad==='missing-past')past=[];if(bad==='changed-past')past=[{...old,content:'변경됨'}];if(bad==='wrong-paragraph')result.updates[0].memoryLinks[0].targetEvidence[0].segmentId='night:p1';if(bad==='manual')d.records[1].manualEdited=true;if(bad==='future')past=[{...old,rowid:99}];if(bad==='same-event-cross-date'){result.updates[0].memoryLinks[0].relation='same_event';d.records[0].episodeId=d.records[1].episodeId;}
 const previous=JSON.stringify(d);assert.throws(()=>C.mergeContinuity(d,result,[now],past));assert.equal(JSON.stringify(d),previous);
});
