function chapterDetailFixtureV104(){const d=C.empty();d.episodes=[{id:'before',title:'진학 고민'},{id:'now',title:'원서 접수'}];d.records=[{id:'old',kind:'event',text:'담임 문자',episodeId:'before',sourceIds:['p']},{id:'event',kind:'event',text:'학교를 고르자는 문답',episodeId:'now',sourceIds:['u','a'],memoryLinks:[{recordId:'old',reason:'접수 기간을 다시 확인',relation:'followup'}]}];const messages=[{id:'p',rowid:1,role:'assistant',content:'담임 문자는 오늘부터 1월 7일까지 원서를 받는다고 알렸다.'},{id:'u',rowid:2,role:'user',content:'한서래 | "언제까지야?"'},{id:'a',rowid:3,role:'assistant',content:'서재헌 | "1월 7일까지야."'}];const sections=C.repairEvidenceIndex(messages).flatMap(m=>m.segments.map(p=>({...p,sourceId:m.sourceId})));return {d,messages,sections,events:[d.records[1]],result:{facts:[{text:'담임은 원서 접수 기간이 오늘부터 1월 7일까지라고 문자로 알렸다.',sourceSegmentNumbers:[1]}],dialogues:[{eventNumber:1,text:'한서래가 접수 마감을 물었다.',quote:'언제까지야?',speaker:'한서래',recipient:'서재헌',channel:'spoken',sourceSegmentNumbers:[2]},{eventNumber:1,text:'서재헌이 한서래의 마감 질문에 1월 7일까지라고 답했다.',quote:'1월 7일까지야.',speaker:'서재헌',recipient:'한서래',channel:'spoken',sourceSegmentNumbers:[3]}]}};}
test('v0104 chapter facts preserve deadline and both-sided exact dialogue atomically and idempotently',()=>{const {d,result,events,sections,messages}=chapterDetailFixtureV104();assert.deepEqual(C.applyChapterDetails(d,result,'now',events,sections,messages),{facts:1,quotes:2});assert.deepEqual(C.applyChapterDetails(d,result,'now',events,sections,messages),{facts:0,quotes:0});assert.equal(C.chapterFacts(d,'now').length,1);assert(C.related(d,[d.records[1]]).some(r=>r.section==='chapter_detail'));assert(!C.personNames(d).includes('접수 기간'));assert.equal(d.records.at(-1).sourceHashes.a,C.hash(messages[2].content));const before=JSON.stringify(d),bad=structuredClone(result);bad.dialogues[1].quote='꾸민 대사';assert.throws(()=>C.applyChapterDetails(d,bad,'now',events,sections,messages),/정확히/);assert.equal(JSON.stringify(d),before);assert.throws(()=>C.applyChapterDetails(d,result,'now',events,sections.map(p=>({...p,text:'위조'})),messages),/실제 원문/);});
test('v0104 chapter detail supplementation respects deleted quotes and manual events',()=>{const {d,result,events,sections,messages}=chapterDetailFixtureV104();C.applyChapterDetails(d,result,'now',events,sections,messages);d.records.filter(r=>r.kind==='quote').forEach(r=>r.deleted=true);assert.equal(C.applyChapterDetails(d,result,'now',events,sections,messages).quotes,0);d.records[1].manualEdited=true;assert.throws(()=>C.applyChapterDetails(d,result,'now',events,sections,messages),/원래 사건/);});
