test('v01011 event evidence reports every copied quote paragraph with actual allowed parent sections',()=>{const x=hotelDialogueFixture108();x.review.dialogues[7].eventNumber=1;x.review.dialogues[7].eventSourceSegmentNumbers=x.review.dialogues[7].sourceSegmentNumbers;x.review.dialogues[8].eventNumber=1;x.review.dialogues[8].eventSourceSegmentNumbers=x.review.dialogues[8].sourceSegmentNumbers;const snapshot=JSON.stringify(x);assert.throws(()=>C.mergeDialogueReview(x.base,x.review,x.messages,[],x.d),e=>{assert.equal(e.code,'MEMORY_REFERENCES');assert.equal(e.repairFeedback.type,'dialogue_event_evidence');assert.deepEqual(e.repairFeedback.issues.map(i=>i.dialogueNumber),[8,9]);for(const i of e.repairFeedback.issues){assert.equal(i.eventRef,'travel');assert.deepEqual(i.eventSourceIds,[x.messages[0].id]);assert(i.allowedEventSourceSegmentNumbers.length);assert(e.repairFeedback.eventEvidenceIndex[0].allowedEventSections.every(p=>p.sourceId===x.messages[0].id));assert(!i.allowedEventSourceSegmentNumbers.includes(i.reportedEventSourceSegmentNumbers[0]));assert(x.messages[0].content.includes(e.repairFeedback.eventEvidenceIndex[0].allowedEventSections[0].text));}return true;});assert.equal(JSON.stringify(x),snapshot);});
