test('v01010 actual two HTML bubble lines survive review validation storage and source edit invalidation',()=>{const x=htmlChatFixture1010(),d=C.empty(),out=C.mergeDialogueReview(x.base,x.review,x.messages,[],d);assert(!x.content.includes(x.quote));assert(C.htmlQuoteView(x.content).text.includes(x.quote));const evidence=C.matchEvidence(x.content,x.quote);assert(evidence&&x.content.includes(evidence)&&evidence.includes('</div>'));C.validateDetailReview(out,x.messages);C.applyExtraction(d,C.detailedResult(out,d,x.messages,{player:'한서래',character:'서재헌'}),x.messages,{allowUnlinkedQuotes:true});const q=d.records.find(r=>r.kind==='quote');assert.equal(q.quote,x.quote);assert.equal(q.channel,'written');assert.equal(q.quoteVerified,true);assert.equal(q.sourceHashes[x.messages[0].id],C.hash(x.content));assert.equal(q.quoteDisplayEvidence[0].format,'html_visible');assert.equal(q.quoteDisplayEvidence[0].sourceId,x.messages[0].id);assert.equal(x.content.slice(q.quoteDisplayEvidence[0].start,q.quoteDisplayEvidence[0].end).startsWith(x.first),true);assert.equal(d.records.find(r=>r.id===q.eventId).kind,'event');C.markEdits(d,[{...x.messages[0],content:x.content.replace(x.second,'다른 대사')}]);assert(q.stale);});
test('v01010 HTML inline tags and supported named numeric entities preserve exact visible punctuation',()=>{const x=htmlChatFixture1010();x.messages[0].content='<div><span>서재헌</span><p>조심해. <b>너 &amp; 나</b> &#x1F352; &#39;약속&#39;.</p><p>그대로야.</p></div>';x.review.dialogues[0].quote="조심해. 너 & 나 🍒 '약속'.\n그대로야.";const out=C.mergeDialogueReview(x.base,x.review,x.messages);assert.equal(out.memories.at(-1).quote,x.review.dialogues[0].quote);assert.equal(C.repairEvidenceIndex(x.messages)[0].segments[0].contentFormat,'html');assert(C.repairEvidenceIndex(x.messages)[0].segments[0].visibleText.includes(x.review.dialogues[0].quote));});
test('v01010 HTML visible matching never skips intervening names times or another bubble and never rewrites wording',()=>{for(const bad of ['space','missing','punctuation','time']){const x=htmlChatFixture1010();if(bad==='space')x.review.dialogues[0].quote=x.first+' '+x.second;if(bad==='missing')x.messages[0].content=x.content.replace(x.second,'중간 답변</div><div>'+x.second);if(bad==='punctuation')x.review.dialogues[0].quote=x.quote.replace('근데 어쩌지?','근데 어쩌지!');if(bad==='time')x.messages[0].content=x.content.replace(x.second,'00:02</div><span>한서래</span><div>'+x.second);assert.throws(()=>C.mergeDialogueReview(x.base,x.review,x.messages),e=>{assert.equal(e.repairFeedback.type,'dialogue_exact_evidence');assert.equal(e.repairFeedback.dialogueNumber,1);assert.equal(typeof e.repairFeedback.selectedSections[0].visibleText,'string');return true;},bad);}});
