function sharedSpeakerFixture1020(){const id='O8mPSVxOGsiDSvrypHUJb',messages=[{id,rowid:1,role:'assistant',content:Array.from({length:63},(_,i)=>i===48||i===50?'서재헌 | "네."':i===56?'직원 | "'+phoneQuote1017+'"':'서재헌 | "'+(i+1)+'번째 고유 발언입니다."').join('\n\n')}],base={processedIds:[id],coverage:[{sourceId:id,outcome:'captured',reason:'통화 및 휴대폰 안내'}],memories:[{ref:'event',kind:'event',text:'실장과 통화한 후 직원이 휴대폰 보관을 안내했다.',sourceIds:[id]}]},rows=C.dialogueCandidates(messages).map((c,i)=>({candidateNumber:i+1,eventNumber:1,speaker:c.speaker,recipient:c.speaker==='직원'?'서재헌':'실장',channel:'spoken',text:'통화의 질문 또는 환자 휴대폰 보관에 대한 응답',linkReason:'같은 원문의 해당 화자가 한 실제 안내와 응답'}));return {messages,base,rows,id};}
